CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE projects(id TEXT PRIMARY KEY,name TEXT NOT NULL,folder TEXT,archived INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE agent_definitions(id TEXT PRIMARY KEY,project_id TEXT REFERENCES projects(id),config_json TEXT NOT NULL,revision INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE sessions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),name TEXT NOT NULL,mode TEXT NOT NULL DEFAULT 'direct' CHECK(mode IN ('direct','collaborative')),epoch INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE instances(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),session_id TEXT NOT NULL REFERENCES sessions(id),agent_id TEXT NOT NULL REFERENCES agent_definitions(id),name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('main','manager')),config_json TEXT NOT NULL,workspace_json TEXT NOT NULL,active_run_id TEXT,created_at INTEGER NOT NULL);
CREATE INDEX instances_session ON instances(session_id,agent_id,created_at);
CREATE UNIQUE INDEX instances_identity ON instances(session_id,agent_id,name,role);
CREATE TABLE budgets(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),session_id TEXT REFERENCES sessions(id),root_run_id TEXT,root_workflow_run_id TEXT,policy_json TEXT NOT NULL,started_at INTEGER,created_at INTEGER NOT NULL,idempotency_key TEXT,input_hash TEXT,UNIQUE(project_id,idempotency_key),CHECK(root_run_id IS NULL OR root_workflow_run_id IS NULL));
CREATE TABLE runs(id TEXT PRIMARY KEY,instance_id TEXT NOT NULL REFERENCES instances(id),root_run_id TEXT,root_workflow_run_id TEXT,parent_run_id TEXT REFERENCES runs(id),workflow_run_id TEXT,budget_id TEXT NOT NULL REFERENCES budgets(id),state TEXT NOT NULL CHECK(state IN ('accepted','running','waiting','completed','failed','cancelled','needs_review')),input_json TEXT NOT NULL,result_json TEXT,error_json TEXT,wait_json TEXT,idempotency_key TEXT NOT NULL,input_hash TEXT NOT NULL,model_role TEXT NOT NULL CHECK(model_role IN ('main','manager')),cancel_requested_at INTEGER,stopped_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,config_json TEXT NOT NULL DEFAULT '{}',source_message_id TEXT REFERENCES messages(id),policy_json TEXT NOT NULL DEFAULT '{}',artifact_count INTEGER NOT NULL DEFAULT 0,display_json TEXT NOT NULL DEFAULT '{}',UNIQUE(instance_id,idempotency_key),CHECK((root_run_id IS NOT NULL)+(root_workflow_run_id IS NOT NULL)=1));
CREATE INDEX runs_instance ON runs(instance_id,state,created_at);
CREATE INDEX runs_state ON runs(state,updated_at);
CREATE INDEX runs_parent ON runs(parent_run_id);
CREATE INDEX runs_root ON runs(root_run_id,state);
CREATE INDEX runs_root_workflow ON runs(root_workflow_run_id,state);
CREATE INDEX runs_workflow ON runs(workflow_run_id,state);
CREATE TABLE run_resumptions(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(id),idempotency_key TEXT NOT NULL,input_hash TEXT NOT NULL,input_json TEXT NOT NULL,interrupt_id TEXT,applied_at INTEGER,created_at INTEGER NOT NULL,event_position INTEGER NOT NULL,source_message_id TEXT REFERENCES messages(id),failure_json TEXT,execution_limits_json TEXT NOT NULL DEFAULT '{}',UNIQUE(run_id,idempotency_key));
CREATE INDEX resumptions_pending ON run_resumptions(run_id,created_at);
CREATE TABLE tool_intents(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),consumer_id TEXT NOT NULL,name TEXT NOT NULL,binding_json TEXT NOT NULL,idempotency_key TEXT NOT NULL,input_hash TEXT NOT NULL,input_json TEXT NOT NULL,cancel_requested_at INTEGER,created_at INTEGER NOT NULL,UNIQUE(project_id,consumer_id,idempotency_key));
CREATE TABLE actions(id TEXT PRIMARY KEY,run_id TEXT REFERENCES runs(id),operation_key TEXT NOT NULL,name TEXT NOT NULL,input_hash TEXT NOT NULL,input_json TEXT,side_effects TEXT NOT NULL CHECK(side_effects IN ('none','local','external')),state TEXT NOT NULL CHECK(state IN ('intent','dispatched','completed','failed','needs_review')),result_json TEXT,error_json TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,intent_id TEXT UNIQUE REFERENCES tool_intents(id),UNIQUE(run_id,operation_key),CHECK((run_id IS NOT NULL)+(intent_id IS NOT NULL)=1),CHECK((run_id IS NOT NULL AND input_json IS NOT NULL) OR (intent_id IS NOT NULL AND input_json IS NULL)));
CREATE INDEX actions_pending ON actions(state,run_id);
CREATE INDEX actions_tool ON actions(name);
CREATE TABLE tool_contracts(id TEXT PRIMARY KEY,spec_json TEXT NOT NULL);
CREATE TABLE action_contracts(action_id TEXT PRIMARY KEY REFERENCES actions(id),contract_id TEXT NOT NULL REFERENCES tool_contracts(id));
CREATE TABLE action_resolutions(action_id TEXT PRIMARY KEY REFERENCES actions(id),idempotency_key TEXT NOT NULL,input_hash TEXT NOT NULL,evidence TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN ('completed','not_applied')),previous_error_json TEXT,created_at INTEGER NOT NULL);
CREATE TABLE usage(id TEXT PRIMARY KEY,budget_id TEXT NOT NULL REFERENCES budgets(id),run_id TEXT NOT NULL REFERENCES runs(id),action_id TEXT,purpose TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('model','tool')),state TEXT NOT NULL CHECK(state IN ('reserved','settled','needs_review')),input_tokens INTEGER NOT NULL DEFAULT 0,cached_input_tokens INTEGER,output_tokens INTEGER NOT NULL DEFAULT 0,estimated INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE INDEX usage_budget ON usage(budget_id,state);
CREATE INDEX usage_action ON usage(action_id,created_at);
CREATE TABLE model_failures(id TEXT PRIMARY KEY REFERENCES usage(id),action_id TEXT NOT NULL REFERENCES actions(id),input_hash TEXT NOT NULL,input_json TEXT NOT NULL,result_json TEXT,error_json TEXT,created_at INTEGER NOT NULL);
CREATE INDEX model_failures_action ON model_failures(action_id,created_at);
CREATE TABLE run_progress(run_id TEXT NOT NULL REFERENCES runs(id),fingerprint TEXT NOT NULL,source TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(run_id,fingerprint));
CREATE TABLE run_activity(run_id TEXT PRIMARY KEY REFERENCES runs(id),stalled_model_calls INTEGER NOT NULL DEFAULT 0,blocker_json TEXT,blocker_signature TEXT,blocker_repeats INTEGER NOT NULL DEFAULT 0);
CREATE TABLE context_sources(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),instance_id TEXT NOT NULL REFERENCES instances(id),run_id TEXT NOT NULL REFERENCES runs(id),origin TEXT NOT NULL,sha256 TEXT NOT NULL,body TEXT,action_id TEXT REFERENCES actions(id),created_at INTEGER NOT NULL,CHECK(body IS NOT NULL OR action_id IS NOT NULL));
CREATE INDEX context_sources_instance ON context_sources(instance_id,created_at);
CREATE UNIQUE INDEX context_sources_identity ON context_sources(instance_id,origin,sha256);
CREATE TABLE context_grants(source_id TEXT NOT NULL REFERENCES context_sources(id),instance_id TEXT NOT NULL REFERENCES instances(id),message_id TEXT,PRIMARY KEY(source_id,instance_id));
CREATE TABLE skill_loads(run_id TEXT NOT NULL REFERENCES runs(id),skill_id TEXT NOT NULL,path TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES context_sources(id),source_path TEXT NOT NULL,PRIMARY KEY(run_id,skill_id,path,source_path));
CREATE TABLE conversation(position INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,instance_id TEXT NOT NULL REFERENCES instances(id),run_id TEXT NOT NULL REFERENCES runs(id),role TEXT NOT NULL,body_json TEXT,action_id TEXT REFERENCES actions(id),input_run_id TEXT REFERENCES runs(id),resumption_id TEXT REFERENCES run_resumptions(id),message_id TEXT REFERENCES messages(id),tool_call_id TEXT,created_at INTEGER NOT NULL,CHECK((body_json IS NOT NULL)+(action_id IS NOT NULL)+(input_run_id IS NOT NULL)+(resumption_id IS NOT NULL)+(message_id IS NOT NULL)=1));
CREATE INDEX conversation_instance ON conversation(instance_id,position);
CREATE TABLE memories(id TEXT PRIMARY KEY,instance_id TEXT NOT NULL REFERENCES instances(id),run_id TEXT NOT NULL REFERENCES runs(id),through_position INTEGER NOT NULL,source_ids_json TEXT NOT NULL,body TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX memories_instance ON memories(instance_id);
CREATE TABLE messages(position INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),session_id TEXT NOT NULL REFERENCES sessions(id),source_json TEXT NOT NULL,purpose TEXT NOT NULL CHECK(purpose IN ('inform','request','reply','report')),body TEXT NOT NULL,root_run_id TEXT REFERENCES runs(id),root_workflow_run_id TEXT REFERENCES workflow_runs(id),reply_to TEXT REFERENCES messages(id),topic_id TEXT,idempotency_key TEXT NOT NULL,input_hash TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(session_id,idempotency_key));
CREATE INDEX messages_session ON messages(session_id,position);
CREATE TABLE message_context_refs(message_id TEXT NOT NULL REFERENCES messages(id),source_id TEXT NOT NULL REFERENCES context_sources(id),PRIMARY KEY(message_id,source_id));
CREATE TABLE deliveries(message_id TEXT NOT NULL REFERENCES messages(id),instance_id TEXT NOT NULL REFERENCES instances(id),run_id TEXT REFERENCES runs(id),accepted_at INTEGER NOT NULL,started_at INTEGER,applied_at INTEGER,completed_at INTEGER,rejected_at INTEGER,reason TEXT,PRIMARY KEY(message_id,instance_id));
CREATE INDEX deliveries_pending ON deliveries(instance_id,applied_at,rejected_at);
CREATE TABLE read_positions(consumer_id TEXT NOT NULL,session_id TEXT NOT NULL REFERENCES sessions(id),position INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(consumer_id,session_id));
CREATE TABLE instance_read_positions(consumer_id TEXT NOT NULL,instance_id TEXT NOT NULL REFERENCES instances(id),position INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(consumer_id,instance_id));
CREATE INDEX instance_read_positions_instance ON instance_read_positions(instance_id);
CREATE TABLE artifacts(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),instance_id TEXT REFERENCES instances(id),run_id TEXT REFERENCES runs(id),name TEXT NOT NULL,path TEXT NOT NULL,sha256 TEXT NOT NULL,bytes INTEGER NOT NULL,media_type TEXT NOT NULL,created_at INTEGER NOT NULL,session_id TEXT REFERENCES sessions(id),origin TEXT NOT NULL CHECK(origin IN ('run','upload','import')),CHECK((origin='run' AND instance_id IS NOT NULL AND run_id IS NOT NULL AND session_id IS NOT NULL) OR (origin!='run' AND instance_id IS NULL AND run_id IS NULL)));
CREATE INDEX artifacts_run ON artifacts(run_id,created_at);
CREATE INDEX artifacts_session ON artifacts(session_id,created_at);
CREATE TABLE run_artifacts(run_id TEXT NOT NULL REFERENCES runs(id),artifact_id TEXT NOT NULL REFERENCES artifacts(id),PRIMARY KEY(run_id,artifact_id));
CREATE TABLE artifact_uploads(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),session_id TEXT REFERENCES sessions(id),consumer_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,input_hash TEXT NOT NULL,name TEXT NOT NULL,bytes INTEGER NOT NULL,sha256 TEXT NOT NULL,media_type TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(project_id,consumer_id,idempotency_key));
CREATE TABLE workflows(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),name TEXT NOT NULL,revision INTEGER NOT NULL,graph_json TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,description TEXT NOT NULL DEFAULT '',state TEXT NOT NULL DEFAULT 'active' CHECK(state IN ('active','archived','deleted')));
CREATE TABLE workflow_runs(id TEXT PRIMARY KEY,workflow_id TEXT NOT NULL REFERENCES workflows(id),session_id TEXT NOT NULL REFERENCES sessions(id),budget_id TEXT NOT NULL REFERENCES budgets(id),root_run_id TEXT,root_workflow_run_id TEXT,parent_workflow_run_id TEXT REFERENCES workflow_runs(id),revision INTEGER NOT NULL,graph_json TEXT NOT NULL,inputs_json TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('accepted','running','waiting','completed','failed','cancelled','needs_review')),result_json TEXT,error_json TEXT,wait_json TEXT,idempotency_key TEXT NOT NULL,input_hash TEXT NOT NULL,cancel_requested_at INTEGER,stopped_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(workflow_id,idempotency_key),CHECK((root_run_id IS NOT NULL)+(root_workflow_run_id IS NOT NULL)=1));
CREATE INDEX workflow_runs_parent ON workflow_runs(parent_workflow_run_id,state);
CREATE INDEX workflow_runs_state ON workflow_runs(state,updated_at);
CREATE INDEX workflow_runs_live ON workflow_runs(workflow_id,state) WHERE state IN ('accepted','running','waiting','needs_review');
CREATE TABLE workflow_steps(id TEXT PRIMARY KEY,workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(id),node_id TEXT NOT NULL,operation_key TEXT NOT NULL,input_hash TEXT NOT NULL,checkpoint_id TEXT NOT NULL,native_step INTEGER NOT NULL,state TEXT NOT NULL,ref_json TEXT,error_json TEXT,outcome_hash TEXT,repair_request_id TEXT REFERENCES workflow_resumptions(id),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(workflow_run_id,node_id,operation_key));
CREATE TABLE workflow_step_failures(step_id TEXT NOT NULL REFERENCES workflow_steps(id),outcome_hash TEXT NOT NULL,state TEXT NOT NULL,ref_json TEXT,error_json TEXT,created_at INTEGER NOT NULL,PRIMARY KEY(step_id,outcome_hash));
CREATE TABLE workflow_nodes(workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(id),node_id TEXT NOT NULL,state TEXT NOT NULL,head_step_id TEXT REFERENCES workflow_steps(id),error_json TEXT,updated_at INTEGER NOT NULL,PRIMARY KEY(workflow_run_id,node_id));
CREATE TABLE workflow_map_members(step_id TEXT NOT NULL REFERENCES workflow_steps(id),ordinal INTEGER NOT NULL,instance_id TEXT REFERENCES instances(id),run_id TEXT REFERENCES runs(id),error_json TEXT,PRIMARY KEY(step_id,ordinal));
CREATE TABLE workflow_resumptions(id TEXT PRIMARY KEY,workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(id),idempotency_key TEXT NOT NULL,interrupt_id TEXT,input_json TEXT NOT NULL,input_hash TEXT NOT NULL,created_at INTEGER NOT NULL,checkpoint_id TEXT,repair_steps_json TEXT NOT NULL DEFAULT '[]',applied_at INTEGER,execution_limits_json TEXT NOT NULL DEFAULT '{}',failure_json TEXT,UNIQUE(workflow_run_id,idempotency_key));
CREATE TABLE events(position INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,project_id TEXT,session_id TEXT,instance_id TEXT,run_id TEXT,data_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX events_session ON events(session_id,position);
CREATE INDEX events_project ON events(project_id,position);
CREATE INDEX events_run ON events(run_id,kind,position);
CREATE TABLE result_refs(id TEXT PRIMARY KEY,consumer_id TEXT NOT NULL,project_id TEXT REFERENCES projects(id),operation TEXT NOT NULL,params_json TEXT NOT NULL,version_json TEXT NOT NULL,overlay_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE result_snapshots(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),consumer_id TEXT NOT NULL,sha256 TEXT NOT NULL,payload_json TEXT NOT NULL,characters INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX result_snapshots_project ON result_snapshots(project_id);
CREATE TABLE mcp_servers(id TEXT PRIMARY KEY,project_id TEXT REFERENCES projects(id),config_json TEXT NOT NULL,revision INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE mcp_catalogs(server_id TEXT NOT NULL REFERENCES mcp_servers(id),revision INTEGER NOT NULL,tools_json TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(server_id,revision));
CREATE TABLE run_mcp_bindings(run_id TEXT NOT NULL REFERENCES runs(id),server_id TEXT NOT NULL REFERENCES mcp_servers(id),revision INTEGER NOT NULL,PRIMARY KEY(run_id,server_id));
CREATE TABLE skills(id TEXT PRIMARY KEY,project_id TEXT REFERENCES projects(id),config_json TEXT NOT NULL,revision INTEGER NOT NULL,removed INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL);
CREATE TABLE skill_bodies(sha256 TEXT PRIMARY KEY,body TEXT NOT NULL);
CREATE TABLE skill_versions(skill_id TEXT NOT NULL REFERENCES skills(id),revision INTEGER NOT NULL,path TEXT NOT NULL,sha256 TEXT NOT NULL REFERENCES skill_bodies(sha256),name TEXT NOT NULL,description TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(skill_id,revision));
CREATE TABLE imported_migrations(id TEXT PRIMARY KEY,source_sha256 TEXT NOT NULL,source_version INTEGER NOT NULL,created_at INTEGER NOT NULL,report_json TEXT NOT NULL);
CREATE TABLE imported_tables(migration_id TEXT NOT NULL REFERENCES imported_migrations(id),name TEXT NOT NULL,ddl TEXT NOT NULL,row_count INTEGER NOT NULL,sha256 TEXT NOT NULL,PRIMARY KEY(migration_id,name));
CREATE TABLE imported_history(position INTEGER PRIMARY KEY AUTOINCREMENT,migration_id TEXT NOT NULL REFERENCES imported_migrations(id),table_name TEXT NOT NULL,row_key TEXT NOT NULL,row_json TEXT NOT NULL,sha256 TEXT NOT NULL,project_id TEXT,session_id TEXT,instance_id TEXT,review_state TEXT NOT NULL CHECK(review_state IN ('history','needs_review')),created_at INTEGER NOT NULL,UNIQUE(migration_id,table_name,row_key));
CREATE INDEX imported_history_scope ON imported_history(project_id,table_name,position);
CREATE INDEX imported_history_session ON imported_history(session_id,instance_id,position);
CREATE TABLE imported_transcript(history_position INTEGER PRIMARY KEY REFERENCES imported_history(position),session_id TEXT NOT NULL,instance_id TEXT,source_position INTEGER NOT NULL,role TEXT NOT NULL,created_at INTEGER NOT NULL,read_at INTEGER);
CREATE INDEX imported_transcript_instance ON imported_transcript(instance_id,source_position);
CREATE TABLE imported_links(migration_id TEXT NOT NULL REFERENCES imported_migrations(id),table_name TEXT NOT NULL,source_id TEXT NOT NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,PRIMARY KEY(migration_id,table_name,source_id,target_type));
CREATE TABLE imported_files(migration_id TEXT NOT NULL REFERENCES imported_migrations(id),relative_path TEXT NOT NULL,sha256 TEXT NOT NULL,bytes INTEGER NOT NULL,PRIMARY KEY(migration_id,relative_path));
CREATE TABLE run_tool_state(run_id TEXT NOT NULL REFERENCES runs(id),name TEXT NOT NULL,contract_id TEXT REFERENCES tool_contracts(id),loaded INTEGER NOT NULL,pinned INTEGER NOT NULL DEFAULT 0,loaded_step INTEGER NOT NULL,last_used_step INTEGER,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(run_id,name));
